/**
 * Packages the Noto interface into the APK.
 *
 * Android's application is a WebView around the `@noto/ui` build — the same
 * interface the web and desktop applications render. `@noto/mobile-webview`
 * compiles it to `apps/mobile/assets/webapp`; this copies that into the
 * generated Android project's asset folder, where Gradle packages it and the
 * WebView can load it from `file:///android_asset/webapp/index.html`.
 *
 * `apps/mobile/android` is regenerated by `expo prebuild`, so this cannot be a
 * hand-copy done once — it has to be reapplied on every generation, which is
 * what a config plugin is for. Companion to `with-android-app-size.cjs` and
 * `with-android-release-signing.cjs`.
 *
 * Note for local work: prebuild is what moves the files. After rebuilding the
 * interface, run `expo prebuild --platform android` again, or point the app at
 * a dev server with `EXPO_PUBLIC_NOTO_WEBAPP_URL` and skip the copy entirely.
 */

const fs = require('node:fs');
const path = require('node:path');

const { withDangerousMod } = require('expo/config-plugins');

/** Where Gradle looks, relative to `apps/mobile/android`. */
const TARGET = path.join('app', 'src', 'main', 'assets', 'webapp');

/**
 * Locates the built interface.
 *
 * Resolved through the module system rather than as a relative path, so this
 * keeps working if either package moves. `@noto/mobile-webview` is a declared
 * dependency of `@noto/mobile` precisely so that this resolution is guaranteed
 * — the application genuinely cannot be built without it.
 */
function interfaceBuildDirectory() {
  const manifest = require.resolve('@noto/mobile-webview/package.json');
  return path.join(path.dirname(manifest), 'dist');
}

module.exports = function withAndroidWebapp(config) {
  return withDangerousMod(config, [
    'android',
    (dangerousConfig) => {
      const from = interfaceBuildDirectory();
      const to = path.join(dangerousConfig.modRequest.platformProjectRoot, TARGET);

      /*
       * Failing here is deliberate. Carrying on would produce an APK that
       * installs, launches, and shows nothing but a blank screen — and it
       * would say so only on a device, long after the build went green.
       */
      if (!fs.existsSync(path.join(from, 'index.html'))) {
        throw new Error(
          `with-android-webapp found no interface at ${from}. ` +
            'Build it first: pnpm build --filter=@noto/mobile-webview...',
        );
      }

      // Replaced rather than merged, so a file dropped from a later build does
      // not linger in the APK.
      fs.rmSync(to, { recursive: true, force: true });
      fs.mkdirSync(path.dirname(to), { recursive: true });
      fs.cpSync(from, to, { recursive: true });

      return dangerousConfig;
    },
  ]);
};
